export { Progress } from './Progress';
export type {
  ProgressBarProps,
  ProgressCircleProps,
  ProgressGradient,
  ProgressProps,
  ProgressSize,
  ProgressVariant,
} from './Progress.types';

import { cn } from '../../utils';

import type { ProgressBarProps, ProgressCircleProps, ProgressProps } from './Progress.types';

const resolveHeightForSize = (size: ProgressProps['size'] = 'md'): string => {
  if (size === 'sm') {
    return '0.5rem';
  }
  if (size === 'lg') {
    return '1.5rem';
  }
  return '1rem';
};

/**
 * Progress Bar - individual bar for stacked progress
 *
 * @example
 * ```tsx
 * <Progress>
 *   <Progress.Bar value={15} variant="success" />
 *   <Progress.Bar value={30} variant="warning" />
 *   <Progress.Bar value={20} variant="danger" />
 * </Progress>
 * ```
 */
function ProgressBar({
  value,
  variant = 'primary',
  showValue = false,
  valueText,
  formatValue,
  gradient,
  striped = false,
  animated = false,
  className,
  'aria-label': ariaLabel,
  'aria-hidden': ariaHidden = false,
  'data-testid': dataTestId,
  'data-test': dataTest,
}: ProgressBarProps): React.JSX.Element {
  const percentage = Math.min(100, Math.max(0, value));
  const isWarning = variant === 'warning';

  const barClasses = cn(
    'progress-bar',
    !gradient && `bg-${variant}`,
    isWarning && !gradient && 'text-dark',
    striped && 'progress-bar-striped',
    animated && 'progress-bar-animated',
    className
  );

  // Compute display value using formatValue (takes precedence) or valueText or default
  const displayValue = formatValue ? formatValue(percentage, 100) : valueText || `${percentage}%`;

  // Build bar style (gradient overrides variant bg)
  const barStyle: React.CSSProperties = {
    width: `${percentage}%`,
    ...(gradient && {
      background: `linear-gradient(${gradient.direction || 'to right'}, ${gradient.from}, ${gradient.to})`,
    }),
  };

  // Generate default aria-label from variant if not provided (and not hidden)
  const computedAriaLabel = ariaHidden
    ? undefined
    : ariaLabel || `${variant} progress: ${percentage}%`;

  // If aria-hidden, render as purely decorative (no ARIA attributes)
  if (ariaHidden) {
    return (
      <div
        className={barClasses}
        style={barStyle}
        aria-hidden="true"
        data-testid={dataTestId}
        data-test={dataTest}
      >
        {showValue && displayValue}
      </div>
    );
  }

  return (
    <div
      className={barClasses}
      role="progressbar"
      style={barStyle}
      aria-valuenow={percentage}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label={computedAriaLabel}
      data-testid={dataTestId}
      data-test={dataTest}
    >
      {showValue && displayValue}
    </div>
  );
}

ProgressBar.displayName = 'Progress.Bar';

/**
 * Render discrete step segments for the progress bar (Ant Design-style)
 */
function renderSteps(
  steps: number,
  percentage: number,
  barClasses: string,
  _barStyle: React.CSSProperties,
  gradient?: { from: string; to: string; direction?: string }
): React.JSX.Element {
  const filledSteps = Math.round((percentage / 100) * steps);
  const gapSize = 2; // px gap between segments

  return (
    <>
      {Array.from({ length: steps }, (_, i) => {
        const isFilled = i < filledSteps;
        // For gradient, interpolate color per segment
        const segmentStyle: React.CSSProperties = {
          width: `calc(${100 / steps}% - ${gapSize}px)`,
          marginRight: i < steps - 1 ? `${gapSize}px` : undefined,
          opacity: isFilled ? 1 : 0.2,
          ...(isFilled &&
            gradient && {
              background: `linear-gradient(${gradient.direction || 'to right'}, ${gradient.from}, ${gradient.to})`,
            }),
        };

        return (
          <div
            key={i}
            className={isFilled ? barClasses : 'progress-bar'}
            style={segmentStyle}
            aria-hidden="true"
            data-step={i + 1}
          />
        );
      })}
    </>
  );
}

/**
 * Progress Component
 *
 * A Bootstrap 5 progress bar component for showing progress or loading states.
 * Supports determinate (with value) and indeterminate (loading) modes.
 *
 * @see https://getbootstrap.com/docs/5.3/components/progress/
 *
 * @example
 * ```tsx
 * // Basic progress bar
 * <Progress value={75} />
 *
 * // With label and value display
 * <Progress value={50} label="Uploading files..." showValue />
 *
 * // Indeterminate loading state
 * <Progress indeterminate variant="info" />
 *
 * // Striped and animated
 * <Progress value={60} striped animated variant="success" />
 *
 * // Different sizes
 * <Progress value={40} size="sm" />
 * <Progress value={40} size="lg" />
 *
 * // Stacked progress bars
 * <Progress>
 *   <Progress.Bar value={15} variant="success" />
 *   <Progress.Bar value={30} variant="warning" />
 *   <Progress.Bar value={20} variant="danger" />
 * </Progress>
 * ```
 *
 * Accessibility Features (WCAG 2.2 AA):
 * - `role="progressbar"` for screen readers
 * - `aria-valuenow`, `aria-valuemin`, `aria-valuemax` for progress state
 * - `aria-valuetext` for custom value descriptions
 * - `aria-busy="true"` for indeterminate state
 * - `aria-label` support for accessible naming
 */
function ProgressBase({
  value,
  variant = 'primary',
  size = 'md',
  label,
  showValue = false,
  valueText,
  formatValue,
  bufferValue,
  steps,
  gradient,
  indeterminate = false,
  striped = false,
  animated = false,
  min = 0,
  max = 100,
  children,
  className,
  style,
  id,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledBy,
  'data-testid': dataTestId,
  'data-test': dataTest,
}: ProgressProps): React.JSX.Element {
  const percentage = indeterminate ? 0 : Math.min(100, Math.max(0, value ?? 0));
  const hasChildren = Boolean(children);

  // Build progress container classes
  const progressClasses = cn('progress', className);

  // Build progress bar classes (for single bar mode)
  const isWarning = variant === 'warning';
  const barClasses = cn(
    'progress-bar',
    !gradient && `bg-${variant}`,
    isWarning && !gradient && 'text-dark',
    striped && 'progress-bar-striped',
    (animated || indeterminate) && 'progress-bar-animated',
    indeterminate && 'progress-bar-striped' // Indeterminate uses striped animation
  );

  // Compute display value using formatValue > valueText > default percentage
  const displayValue = formatValue ? formatValue(percentage, max) : valueText || `${percentage}%`;

  // Calculate aria-valuetext (must be string for accessibility)
  const computedValueText = indeterminate
    ? 'Loading'
    : typeof displayValue === 'string'
      ? displayValue
      : valueText || `${percentage}%`;

  // Buffer bar percentage
  const bufferPercentage =
    bufferValue != null ? Math.min(100, Math.max(0, bufferValue)) : undefined;

  // Build bar style (gradient overrides variant bg)
  const barStyle: React.CSSProperties = {
    width: indeterminate ? '100%' : `${percentage}%`,
    ...(indeterminate && {
      animation: 'progress-bar-stripes 1s linear infinite',
    }),
    ...(gradient && {
      background: `linear-gradient(${gradient.direction || 'to right'}, ${gradient.from}, ${gradient.to})`,
    }),
  };

  return (
    <div className="d-flex flex-column gap-1">
      {/* Optional label */}
      {label && (
        <div className="d-flex justify-content-between align-items-center">
          <span className="small text-body-secondary">{label}</span>
          {showValue && !indeterminate && !hasChildren && (
            <span className="small fw-medium">{displayValue}</span>
          )}
        </div>
      )}

      {/* Progress bar container */}
      <div
        className={progressClasses}
        style={{
          height: resolveHeightForSize(size),
          ...(bufferPercentage != null && { position: 'relative' as const }),
          ...style,
        }}
        id={id}
        role={hasChildren ? 'group' : 'progressbar'}
        data-testid={dataTestId}
        data-test={dataTest}
        {...(!hasChildren && {
          'aria-label': ariaLabel,
          'aria-labelledby': ariaLabelledBy,
          'aria-valuenow': indeterminate ? undefined : percentage,
          'aria-valuemin': min,
          'aria-valuemax': max,
          'aria-valuetext': computedValueText,
          'aria-busy': indeterminate,
        })}
      >
        {hasChildren ? (
          // Stacked progress bars
          children
        ) : steps != null && steps > 0 ? (
          // Steps/segments mode (similar to Ant Design)
          renderSteps(steps, percentage, barClasses, barStyle, gradient)
        ) : (
          // Single/buffer progress bar
          <>
            {/* Buffer bar (MUI-style) — lighter background behind main bar */}
            {bufferPercentage != null && (
              <div
                className={cn('progress-bar', !gradient && `bg-${variant}`)}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  height: '100%',
                  width: `${bufferPercentage}%`,
                  opacity: 0.3,
                  ...(gradient && {
                    background: `linear-gradient(${gradient.direction || 'to right'}, ${gradient.from}, ${gradient.to})`,
                  }),
                }}
                aria-hidden="true"
                data-testid={dataTestId ? `${dataTestId}-buffer` : undefined}
              />
            )}
            {/* Main progress bar */}
            <div
              className={barClasses}
              style={{
                ...barStyle,
                ...(bufferPercentage != null && { position: 'relative' as const, zIndex: 1 }),
              }}
            >
              {showValue && !indeterminate && !label && displayValue}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

ProgressBase.displayName = 'Progress';

let circleGradientId = 0;

/**
 * Circular Progress indicator (MUI/Ant Design-style)
 *
 * SVG-based ring progress for dashboards and compact displays.
 *
 * @example
 * ```tsx
 * <Progress.Circle value={75} showValue />
 * <Progress.Circle indeterminate variant="info" />
 * ```
 */
function ProgressCircle({
  value,
  variant = 'primary',
  size = 80,
  strokeWidth = 6,
  showValue = false,
  valueText,
  formatValue,
  gradient,
  indeterminate = false,
  min = 0,
  max = 100,
  className,
  style,
  id,
  'aria-label': ariaLabel,
  'data-testid': dataTestId,
  'data-test': dataTest,
}: ProgressCircleProps): React.JSX.Element {
  const percentage = indeterminate ? 0 : Math.min(100, Math.max(0, value ?? 0));
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  // Compute display value
  const displayValue = formatValue ? formatValue(percentage, max) : valueText || `${percentage}%`;

  // Compute aria-valuetext (must be string)
  const computedValueText = indeterminate
    ? 'Loading'
    : typeof displayValue === 'string'
      ? displayValue
      : valueText || `${percentage}%`;

  // Unique gradient ID per instance
  const gradientIdRef = `dsai-circle-gradient-${++circleGradientId}`;

  // Use Bootstrap 5 CSS custom properties for variant colors (no hardcoded hex)
  const strokeColor = gradient ? `url(#${gradientIdRef})` : `var(--bs-${variant})`;

  return (
    <div
      className={cn('dsai-progress-circle', className)}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        width: size,
        height: size,
        ...style,
      }}
      id={id}
      role="progressbar"
      aria-valuenow={indeterminate ? undefined : percentage}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={computedValueText}
      aria-label={ariaLabel}
      aria-busy={indeterminate || undefined}
      data-testid={dataTestId}
      data-test={dataTest}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        aria-hidden="true"
        style={{
          transform: 'rotate(-90deg)',
          ...(indeterminate && {
            animation: 'dsai-circle-spin 1.4s linear infinite',
          }),
        }}
      >
        {/* Gradient definition */}
        {gradient && (
          <defs>
            <linearGradient id={gradientIdRef} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor={gradient.from} />
              <stop offset="100%" stopColor={gradient.to} />
            </linearGradient>
          </defs>
        )}

        {/* Background track */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          opacity={0.15}
        />

        {/* Progress arc */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={indeterminate ? circumference * 0.75 : strokeDashoffset}
          strokeLinecap="round"
          style={{ transition: indeterminate ? 'none' : 'stroke-dashoffset 0.3s ease' }}
        />
      </svg>

      {/* Center value display */}
      {showValue && !indeterminate && (
        <span
          style={{
            position: 'absolute',
            fontSize: size * 0.22,
            fontWeight: 600,
            lineHeight: 1,
          }}
        >
          {displayValue}
        </span>
      )}

      {/* Indeterminate animation styles (injected once) */}
      {indeterminate && (
        <style>{`
          @keyframes dsai-circle-spin {
            0% { transform: rotate(-90deg); }
            100% { transform: rotate(270deg); }
          }
        `}</style>
      )}
    </div>
  );
}

ProgressCircle.displayName = 'Progress.Circle';

// Create compound component
type ProgressComponent = typeof ProgressBase & {
  Bar: typeof ProgressBar;
  Circle: typeof ProgressCircle;
};

export const Progress = ProgressBase as ProgressComponent;
Progress.Bar = ProgressBar;
Progress.Circle = ProgressCircle;

import type { ComponentSize, SemanticColorVariant } from '../../types';
import type { CSSProperties, ReactNode } from 'react';

/**
 * Gradient configuration for progress bars
 * Similar to Ant Design's `strokeColor: { from, to }` pattern
 *
 * @example
 * ```tsx
 * <Progress value={75} gradient={{ from: '#108ee9', to: '#87d068' }} />
 * ```
 */
export interface ProgressGradient {
  /** Start color (left side in LTR) */
  from: string;
  /** End color (right side in LTR) */
  to: string;
  /** Gradient direction
   * @default 'to right'
   */
  direction?: string;
}

/**
 * Progress bar color variants
 * Maps to Bootstrap 5 progress bar background utilities
 * Note: Excludes 'light' variant as it's not visible on light backgrounds
 *
 * @see https://getbootstrap.com/docs/5.3/components/progress/
 * @see SemanticColorVariant
 */
export type ProgressVariant = Exclude<SemanticColorVariant, 'light'>;

/**
 * Progress bar sizes
 * @see ComponentSize
 */
export type ProgressSize = ComponentSize;

/**
 * Progress component props
 *
 * @example
 * ```tsx
 * // Determinate progress bar
 * <Progress value={75} variant="primary" />
 *
 * // Indeterminate (loading) progress bar
 * <Progress indeterminate variant="info" />
 *
 * // With label
 * <Progress value={50} label="Uploading..." showValue />
 *
 * // Striped and animated
 * <Progress value={60} striped animated />
 *
 * // Stacked progress bars
 * <Progress>
 *   <Progress.Bar value={15} variant="success" />
 *   <Progress.Bar value={30} variant="warning" />
 *   <Progress.Bar value={20} variant="danger" />
 * </Progress>
 * ```
 */
export interface ProgressProps {
  /**
   * Progress value (0-100)
   * If undefined and not indeterminate, defaults to 0
   */
  value?: number;

  /**
   * Progress bar color variant
   * @default 'primary'
   */
  variant?: ProgressVariant;

  /**
   * Progress bar size
   * @default 'md'
   */
  size?: ProgressSize;

  /**
   * Optional label displayed above the progress bar
   */
  label?: string;

  /**
   * Show percentage value inside the progress bar
   * @default false
   */
  showValue?: boolean;

  /**
   * Custom value text (overrides percentage display)
   */
  valueText?: string;

  /**
   * Indeterminate mode (animated loading state)
   * @default false
   */
  indeterminate?: boolean;

  /**
   * Striped pattern
   * @default false
   */
  striped?: boolean;

  /**
   * Animated stripes (requires striped to be true)
   * @default false
   */
  animated?: boolean;

  /**
   * Minimum value for aria-valuemin.
   *
   * **Note**: `min` and `max` control ARIA semantics only, not the visual range.
   * The visual width is always calculated as a percentage of 0-100.
   *
   * For example, with `min=10, max=20, value=15`:
   * - Visual width = 50% (since 15 is halfway between 0 and 100 as a percentage)
   * - `aria-valuenow=15`, `aria-valuemin=10`, `aria-valuemax=20`
   *
   * @default 0
   */
  min?: number;

  /**
   * Maximum value for aria-valuemax.
   *
   * **Note**: `min` and `max` control ARIA semantics only, not the visual range.
   * The visual width is always calculated as a percentage of 0-100.
   *
   * @default 100
   */
  max?: number;

  /**
   * Custom value formatter function.
   * Receives current value and max, returns content to display.
   * Takes precedence over `valueText` when both are provided.
   *
   * Similar to Ant Design's `format` and Ark UI's `getValueLabel`.
   *
   * @example
   * ```tsx
   * <Progress value={3} max={10} formatValue={(v, max) => `${v}/${max} items`} showValue />
   * ```
   */
  formatValue?: (value: number, max: number) => ReactNode;

  /**
   * Buffer value (0-100) for showing a secondary lighter bar.
   * Commonly used for video buffering or two-stage progress.
   *
   * Similar to MUI's `variant="buffer"` with `valueBuffer` prop.
   *
   * @example
   * ```tsx
   * <Progress value={30} bufferValue={60} />
   * ```
   */
  bufferValue?: number;

  /**
   * Number of discrete steps/segments to render.
   * Progress fills segments proportionally based on value.
   *
   * Similar to Ant Design's `steps` prop.
   *
   * @example
   * ```tsx
   * <Progress value={60} steps={5} /> // Fills 3 of 5 segments
   * ```
   */
  steps?: number;

  /**
   * Gradient fill for the progress bar.
   * Overrides the variant background color when provided.
   *
   * Similar to Ant Design's `strokeColor: { from, to }`.
   *
   * @example
   * ```tsx
   * <Progress value={75} gradient={{ from: '#108ee9', to: '#87d068' }} />
   * ```
   */
  gradient?: ProgressGradient;

  /**
   * Children for stacked progress bars
   */
  children?: ReactNode;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * ID attribute
   */
  id?: string;

  /**
   * Accessible label for screen readers
   */
  'aria-label'?: string;

  /**
   * ID of element that labels this progress bar
   */
  'aria-labelledby'?: string;

  /**
   * Test ID for testing frameworks
   */
  'data-testid'?: string;

  /**
   * Additional test selector
   */
  'data-test'?: string;
}

/**
 * Progress.Bar component props (for stacked progress bars)
 */
/**
 * Progress.Circle component props
 *
 * SVG-based circular progress indicator.
 * Complements the linear Progress component for dashboard-style displays.
 *
 * @example
 * ```tsx
 * <Progress.Circle value={75} />
 * <Progress.Circle value={75} size={120} showValue />
 * <Progress.Circle indeterminate variant="info" />
 * ```
 */
export interface ProgressCircleProps {
  /** Progress value (0-100) */
  value?: number;

  /** Circle color variant
   * @default 'primary'
   */
  variant?: ProgressVariant;

  /** Diameter of the circle in pixels
   * @default 80
   */
  size?: number;

  /** Stroke width in pixels
   * @default 6
   */
  strokeWidth?: number;

  /** Show value text in the center
   * @default false
   */
  showValue?: boolean;

  /** Custom value text */
  valueText?: string;

  /** Custom value formatter */
  formatValue?: (value: number, max: number) => ReactNode;

  /** Indeterminate (loading) mode
   * @default false
   */
  indeterminate?: boolean;

  /** Gradient fill */
  gradient?: ProgressGradient;

  /** Minimum value for ARIA
   * @default 0
   */
  min?: number;

  /** Maximum value for ARIA
   * @default 100
   */
  max?: number;

  /** Additional CSS class names */
  className?: string;

  /** Inline styles */
  style?: CSSProperties;

  /** ID attribute */
  id?: string;

  /** Accessible label */
  'aria-label'?: string;

  /** Test ID */
  'data-testid'?: string;

  /** Additional test selector */
  'data-test'?: string;
}

export interface ProgressBarProps {
  /**
   * Progress value (0-100)
   */
  value: number;

  /**
   * Progress bar color variant
   * @default 'primary'
   */
  variant?: ProgressVariant;

  /**
   * Show percentage value inside the bar
   * @default false
   */
  showValue?: boolean;

  /**
   * Custom value text
   */
  valueText?: string;

  /**
   * Custom value formatter. Takes precedence over `valueText`.
   */
  formatValue?: (value: number, max: number) => ReactNode;

  /**
   * Gradient fill. Overrides variant background color.
   */
  gradient?: ProgressGradient;

  /**
   * Striped pattern
   * @default false
   */
  striped?: boolean;

  /**
   * Animated stripes
   * @default false
   */
  animated?: boolean;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Accessible label for screen readers.
   * If not provided, defaults to "{variant} progress: {percentage}%".
   */
  'aria-label'?: string;

  /**
   * Mark this progress bar as decorative (hidden from assistive technology).
   * Use this for purely decorative stacked bars where the parent Progress
   * component provides the accessible label.
   *
   * @default false
   */
  'aria-hidden'?: boolean;

  /**
   * Test ID for testing frameworks
   */
  'data-testid'?: string;

  /**
   * Additional test selector
   */
  'data-test'?: string;
}
